# ── answer extraction (mirrors the official VibeThinker eval) ──────────────────
# The official harness (rllm/deepcoder `extract_answer`) grades ONLY the content of
# the model's \boxed{...}, never the full response. Our problems aren't all single
# scalars, so we use two complementary signals:
#   • last_boxed()        — authoritative final answer when the model boxes it
#   • strip_echoed_prompt — removes prompt text the model parroted back, so a digit
#                           echoed from the question (e.g. the "9" in "all but 9
#                           die") can't be mistaken for the model's answer.
# Scoring runs over these, never the raw response — that was the false-PASS bug.
def last_boxed(text: str):
    """Content of the last \\boxed{...} in text (balanced braces), or None."""
    idx = text.rfind("\\boxed")
    if idx < 0:
        return None
    i = text.find("{", idx)
    if i < 0:
        return None
    depth = 0
    for j in range(i, len(text)):
        if text[j] == "{":
            depth += 1
        elif text[j] == "}":
            depth -= 1
            if depth == 0:
                return text[i + 1:j].strip()
    return None


def strip_echoed_prompt(answer: str, prompt: str) -> str:
    """Remove verbatim prompt fragments the model echoed, so prompt numbers/words
    can't satisfy the scorer. Conservative: only strips the full prompt and any
    echoed prompt *line* of >=12 chars, leaving the model's own wording intact."""
    cleaned = answer.replace(prompt.strip(), " ")
    for line in prompt.splitlines():
        line = line.strip()
        if len(line) >= 12 and line in cleaned:
            cleaned = cleaned.replace(line, " ")
    return cleaned


